import React, { useEffect, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import API from '../api';

const emptyForm = {
  name: '', category: '', icon: '🏢', description: '', full_description: '',
  established: '', location: '', license_number: '', phone: '',
  tin_number: '', business_license_number: '', website: '',
  followers: '', growth: '', engagement: '',
};

export default function ClientForm() {
  const { id } = useParams();
  const isEdit = Boolean(id);
  const navigate = useNavigate();

  const [form, setForm] = useState(emptyForm);
  const [images, setImages] = useState([]);
  const [videos, setVideos] = useState([]);
  const [uploading, setUploading] = useState(false);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState('');
  const [mediaDesc, setMediaDesc] = useState('');

  useEffect(() => {
    if (isEdit) {
      API.get(`/clients/${id}`).then(({ data }) => {
        setForm({
          name: data.name || '', category: data.category || '', icon: data.icon || '🏢',
          description: data.description || '', full_description: data.full_description || '',
          established: data.established || '', location: data.location || '',
          license_number: data.license_number || '', phone: data.phone || '',
          tin_number: data.tin_number || '', business_license_number: data.business_license_number || '',
          website: data.website || '', followers: data.followers || '',
          growth: data.growth || '', engagement: data.engagement || '',
        });
        setImages(data.images || []);
        setVideos(data.videos || []);
      });
    }
  }, [id, isEdit]);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSave = async (e) => {
    e.preventDefault();
    setSaving(true);
    setError('');
    try {
      if (isEdit) {
        await API.put(`/clients/${id}`, form);
      } else {
        await API.post('/clients', form);
      }
      navigate('/clients');
    } catch (err) {
      setError(err.response?.data?.message || 'Save failed.');
    } finally {
      setSaving(false);
    }
  };

  const uploadFile = async (file) => {
    if (!isEdit) return alert('Save the client first, then upload media.');
    setUploading(true);
    const fd = new FormData();
    fd.append('file', file);
    fd.append('description', mediaDesc);
    try {
      const { data } = await API.post(`/clients/${id}/media`, fd);
      if (data.type === 'video') setVideos((v) => [...v, data]);
      else setImages((img) => [...img, data]);
      setMediaDesc('');
    } catch (err) {
      alert(err.response?.data?.message || 'Upload failed.');
    } finally {
      setUploading(false);
    }
  };

  const deleteMedia = async (mediaId, type) => {
    if (!window.confirm('Delete this file?')) return;
    await API.delete(`/clients/${id}/media/${mediaId}`);
    if (type === 'video') setVideos((v) => v.filter((x) => x.id !== mediaId));
    else setImages((img) => img.filter((x) => x.id !== mediaId));
  };

  return (
    <div style={{ maxWidth: 800 }}>
      <h1 style={{ fontSize: 24, marginBottom: 28 }}>{isEdit ? 'Edit Client' : 'Add New Client'}</h1>

      {error && <div style={errorBox}>{error}</div>}

      <form onSubmit={handleSave}>
        <Section title="Basic Info">
          <Row>
            <Field label="Business Name *" name="name" value={form.name} onChange={handleChange} required />
            <Field label="Category *" name="category" value={form.category} onChange={handleChange} required />
          </Row>
          <Row>
            <Field label="Icon (emoji)" name="icon" value={form.icon} onChange={handleChange} />
            <Field label="Phone" name="phone" value={form.phone} onChange={handleChange} />
          </Row>
          <Field label="Short Description" name="description" value={form.description} onChange={handleChange} />
          <Field label="Full Description" name="full_description" value={form.full_description} onChange={handleChange} textarea />
        </Section>

        <Section title="Business Details">
          <Row>
            <Field label="Established Year" name="established" value={form.established} onChange={handleChange} />
            <Field label="Location" name="location" value={form.location} onChange={handleChange} />
          </Row>
          <Row>
            <Field label="License Number" name="license_number" value={form.license_number} onChange={handleChange} />
            <Field label="TIN Number" name="tin_number" value={form.tin_number} onChange={handleChange} />
          </Row>
          <Row>
            <Field label="Business License No." name="business_license_number" value={form.business_license_number} onChange={handleChange} />
            <Field label="Website" name="website" value={form.website} onChange={handleChange} />
          </Row>
        </Section>

        <Section title="Social Media Stats">
          <Row>
            <Field label="Followers (e.g. 25K+)" name="followers" value={form.followers} onChange={handleChange} />
            <Field label="Growth (e.g. +180%)" name="growth" value={form.growth} onChange={handleChange} />
            <Field label="Engagement (e.g. 8.5%)" name="engagement" value={form.engagement} onChange={handleChange} />
          </Row>
        </Section>

        <button type="submit" disabled={saving} style={btnPrimary}>
          {saving ? 'Saving...' : isEdit ? 'Save Changes' : 'Create Client'}
        </button>
      </form>

      {isEdit && (
        <>
          <Section title="Upload Media">
            <p style={{ color: '#a3a3a3', fontSize: 13, marginBottom: 12 }}>Upload images and videos for this client's portfolio.</p>
            <input
              type="text"
              placeholder="Description (e.g. Instagram Post - Product Launch)"
              value={mediaDesc}
              onChange={(e) => setMediaDesc(e.target.value)}
              style={{ ...inputStyle, marginBottom: 12 }}
            />
            <div style={{ display: 'flex', gap: 12 }}>
              <label style={uploadBtn}>
                {uploading ? 'Uploading...' : '📸 Upload Image'}
                <input type="file" accept="image/*" hidden onChange={(e) => e.target.files[0] && uploadFile(e.target.files[0])} />
              </label>
              <label style={uploadBtn}>
                {uploading ? 'Uploading...' : '🎬 Upload Video'}
                <input type="file" accept="video/*" hidden onChange={(e) => e.target.files[0] && uploadFile(e.target.files[0])} />
              </label>
            </div>
          </Section>

          {images.length > 0 && (
            <Section title={`Images (${images.length})`}>
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: 12 }}>
                {images.map((img) => (
                  <div key={img.id} style={{ position: 'relative', borderRadius: 10, overflow: 'hidden', background: '#262626' }}>
                    <img src={img.url} alt={img.description} style={{ width: '100%', height: 140, objectFit: 'cover' }} />
                    <div style={{ padding: '8px 10px', fontSize: 12, color: '#a3a3a3' }}>{img.description || 'No description'}</div>
                    <button onClick={() => deleteMedia(img.id, 'image')} style={deleteBtn}>✕</button>
                  </div>
                ))}
              </div>
            </Section>
          )}

          {videos.length > 0 && (
            <Section title={`Videos (${videos.length})`}>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 10 }}>
                {videos.map((v) => (
                  <div key={v.id} style={{ background: '#262626', borderRadius: 10, padding: 14, display: 'flex', alignItems: 'center', gap: 14 }}>
                    <span style={{ fontSize: 28 }}>🎬</span>
                    <div style={{ flex: 1 }}>
                      <div style={{ fontSize: 13, color: '#fff' }}>{v.description || 'No description'}</div>
                      <a href={v.url} target="_blank" rel="noreferrer" style={{ fontSize: 12, color: '#f97316' }}>Preview ↗</a>
                    </div>
                    <button onClick={() => deleteMedia(v.id, 'video')} style={btnDanger}>Delete</button>
                  </div>
                ))}
              </div>
            </Section>
          )}
        </>
      )}
    </div>
  );
}

const Section = ({ title, children }) => (
  <div style={{ background: '#171717', border: '1px solid #262626', borderRadius: 14, padding: 24, marginBottom: 20 }}>
    <h3 style={{ fontSize: 16, marginBottom: 18, color: '#f97316' }}>{title}</h3>
    {children}
  </div>
);

const Row = ({ children }) => (
  <div style={{ display: 'grid', gridTemplateColumns: `repeat(${React.Children.count(children)}, 1fr)`, gap: 14, marginBottom: 0 }}>
    {children}
  </div>
);

const Field = ({ label, name, value, onChange, required, textarea }) => (
  <div style={{ marginBottom: 14 }}>
    <label style={{ display: 'block', fontSize: 13, color: '#a3a3a3', marginBottom: 6 }}>{label}</label>
    {textarea ? (
      <textarea name={name} value={value} onChange={onChange} rows={4} style={{ ...inputStyle, resize: 'vertical' }} />
    ) : (
      <input type="text" name={name} value={value} onChange={onChange} required={required} style={inputStyle} />
    )}
  </div>
);

const inputStyle = { width: '100%', padding: '10px 12px', background: '#0a0a0a', border: '1px solid #333', borderRadius: 8, color: '#fff', fontSize: 14 };
const btnPrimary = { background: '#f97316', color: '#000', border: 'none', padding: '12px 28px', borderRadius: 8, fontWeight: 700, fontSize: 15, marginBottom: 20 };
const btnDanger = { background: '#ef444420', color: '#ef4444', border: '1px solid #ef444440', padding: '6px 12px', borderRadius: 6, fontSize: 13 };
const uploadBtn = { background: '#262626', color: '#fff', border: '1px solid #333', padding: '10px 18px', borderRadius: 8, fontSize: 14, cursor: 'pointer' };
const deleteBtn = { position: 'absolute', top: 6, right: 6, background: '#ef4444', color: '#fff', border: 'none', borderRadius: '50%', width: 24, height: 24, fontSize: 12, cursor: 'pointer' };
const errorBox = { background: '#ef444420', border: '1px solid #ef4444', color: '#ef4444', padding: '10px 14px', borderRadius: 8, marginBottom: 20, fontSize: 14 };
